mapper.select:
select aa.*,nvl(cc.config_id,'N') configid,nvl(TO_CHAR(bb.sdate,'yyyy-MM-dd'),null) sdate,nvl( TO_CHAR(bb.edate,'yyyy-MM-dd'),null) edate from ( select type1,type1code,type2,type2code,ftrtype2,ftrid,EFF_STATUS1 effstatus1,ftrname,FTRVALUESTRUCT,VALUEEXETYPE,FTRVALUESTRUCT1, EFFSTATUS,REMARK from ( select is_visible, b.TIPS_VALUE TIPS_VALUE1, c.TIPS_VALUE TIPS_VALUE2, (select item_value from sys_datadict_list where dict_code = 'FTR_RSK_TYPE' and item_code = b.TIPS_VALUE) type1, (select item_value from sys_datadict_list where dict_code = ( 'FTR_RSK_TYPE'||'_'||b.TIPS_VALUE) and item_code = c.TIPS_VALUE) type2, b.TIPS_VALUE type1code, c.TIPS_VALUE type2code, d.TIPS_VALUE ftrtype2, a.ftr_id ftrid, a.ftr_name ftrname, (select item_value from sys_datadict_list where dict_code = 'VALUE_STRUCT' and item_code = a.FTR_VALUE_STRUCT) FTRVALUESTRUCT, a.FTR_VALUE_STRUCT FTRVALUESTRUCT1, FTR_VALUE_STRUCT FTR_VALUE_STRUCT1, (select item_value from sys_datadict_list where dict_code = 'VALUE_EXE_TYPE' and item_code = a.VALUE_EXE_TYPE) VALUEEXETYPE, (select item_value from sys_datadict_list where dict_code = 'FTR_STATUS' and item_code = a.EFF_STATUS) EFFSTATUS, EFF_STATUS EFF_STATUS1, a.REMARK from STT_FACTOR a left join STT_FACTOR_TIPS b on a.ftr_id= b.FTR_ID and b.dict_code='FTR_RSK_TYPE' left join STT_FACTOR_TIPS c on a.ftr_id= c.FTR_ID and c.dict_code like 'FTR_RSK_TYPE\_%' escape '\' left join STT_FACTOR_TIPS d on a.ftr_id= d.FTR_ID and d.dict_code = 'FTR_RSK_TYPE2' ) where is_visible='E'
and TIPS_VALUE1 =#{type1}
and TIPS_VALUE2 =#{type2}
and ftrtype2 =#{mrkFtrType2}
and ftrid =#{twoClass}
and FTR_VALUE_STRUCT1 =#{FTRVALUESTRUCT}
and EFF_STATUS1 =#{FTRSTATUS}
) aa left join ( select ftr_id,sdate,edate from (select FTR_ID, min(START_DATE) sdate, max(END_DATE) edate from (select STT_SCENE_FACTOR.FTR_ID, STT_SCENE.START_DATE, STT_SCENE.END_DATE from STT_SCENE_FACTOR left join STT_SCENE on STT_SCENE_FACTOR.SCENE_ID = STT_SCENE.SCENE_ID where 1=1
and STT_SCENE_FACTOR.FTR_ID =#{twoClass}
) group by FTR_ID) ) bb on aa.ftrid=bb.ftr_id left join STT_FACTOR_EXT cc on aa.ftrid=cc.ftr_id order by aa.ftrid

select ftrid id,ftrname text,'SEC_NAME' as col from ( select is_visible, b.TIPS_VALUE TIPS_VALUE1, c.TIPS_VALUE TIPS_VALUE2, d.TIPS_VALUE TIPS_VALUE3, (select item_value from sys_datadict_list where dict_code = 'FTR_RSK_TYPE' and item_code = b.TIPS_VALUE) type1, (select item_value from sys_datadict_list where dict_code = ( 'FTR_RSK_TYPE'||'_'||b.TIPS_VALUE) and item_code = c.TIPS_VALUE) type2, a.ftr_id ftrid, a.ftr_name ftrname, (select item_value from sys_datadict_list where dict_code = 'VALUE_STRUCT' and item_code = a.FTR_VALUE_STRUCT) FTRVALUESTRUCT, FTR_VALUE_STRUCT FTR_VALUE_STRUCT1, (select item_value from sys_datadict_list where dict_code = 'VALUE_EXE_TYPE' and item_code = a.VALUE_EXE_TYPE) VALUEEXETYPE, (select item_value from sys_datadict_list where dict_code = 'FTR_STATUS' and item_code = a.EFF_STATUS) EFFSTATUS, EFF_STATUS EFF_STATUS1, a.REMARK from STT_FACTOR a left join STT_FACTOR_TIPS b on a.ftr_id= b.FTR_ID and b.dict_code='FTR_RSK_TYPE' left join STT_FACTOR_TIPS c on a.ftr_id= c.FTR_ID and c.dict_code like 'FTR_RSK_TYPE\_%' escape '\' left join STT_FACTOR_TIPS d on a.ftr_id= d.FTR_ID and d.dict_code='FTR_RSK_TYPE2' ) where is_visible='E'
and TIPS_VALUE1 =#{type1}
and TIPS_VALUE2 =#{type2}
and TIPS_VALUE3 =#{type3}

select ftrid id,ftrname text,'SEC_NAME' as col from ( select is_visible, b.TIPS_VALUE TIPS_VALUE1, c.TIPS_VALUE TIPS_VALUE2, f.TIPS_VALUE TIPS_VALUE3, a.ftr_id ftrid, a.ftr_name ftrname, d.config_id from STT_FACTOR a left join STT_FACTOR_TIPS b on a.ftr_id= b.FTR_ID and b.dict_code='FTR_RSK_TYPE' left join STT_FACTOR_TIPS c on a.ftr_id= c.FTR_ID and c.dict_code like 'FTR_RSK_TYPE\_%' escape '\' left join STT_FACTOR_EXT d on a.ftr_id= d.FTR_ID left join STT_FACTOR_TIPS f on a.ftr_id= f.FTR_ID and f.dict_code='FTR_RSK_TYPE2' ) where is_visible='E' and config_id is not null
and TIPS_VALUE1 =#{type1}
and TIPS_VALUE2 =#{type2}
and TIPS_VALUE3 =#{type3}


select ITEM_CODE id,ITEM_VALUE text,'SEC_TYPE2' as col from sys_datadict_list where 1=1
and DICT_CODE like  'FTR_RSK_TYPE\_%' escape '\'

    and DICT_CODE=#{dicode}
